create extension if not exists pgcrypto;
create type public.lead_status as enum ('scheduled','completed','cancelled');
create type public.service_frequency as enum ('one_time','weekly','biweekly','monthly');
create type public.payment_method as enum ('cash','transfer');
create table public.services(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug~'^[a-z0-9-]+$'),name_en text not null,name_es text not null,description_en text not null,description_es text not null,starting_price numeric(10,2) not null default 0 check(starting_price>=0),pricing_unit text,image_url text,active boolean not null default true,featured boolean not null default false,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.pricing_rules(id uuid primary key default gen_random_uuid(),service_id uuid not null references public.services on delete cascade,min_sqft integer not null check(min_sqft>=0),max_sqft integer check(max_sqft is null or max_sqft>=min_sqft),price numeric(10,2) not null check(price>0),frequency service_frequency not null,active boolean not null default true,created_at timestamptz not null default now(),unique(service_id,min_sqft,max_sqft,frequency));
create table public.service_areas(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,content_en text not null,content_es text not null,active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),full_name text not null,email text,phone text not null,email_normalized text,phone_normalized text,property_address text not null,latitude double precision,longitude double precision,lawn_sqft numeric,lawn_geometry jsonb,requested_date date,requested_time time,frequency service_frequency,service_id uuid references public.services, waste_handling text,notes text,payment_method payment_method,estimated_price numeric(10,2),status lead_status not null default 'scheduled',source text not null default 'quote',completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.lead_services(lead_id uuid references public.leads on delete cascade,service_id uuid references public.services,primary key(lead_id,service_id));
create table public.gallery(id uuid primary key default gen_random_uuid(),image_url text not null check(image_url~'^https://'),storage_path text unique not null,caption_en text,caption_es text,alt_text text not null,sort_order integer not null default 0,published boolean not null default false,created_at timestamptz not null default now());
create table public.site_settings(key text primary key,value jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.admin_profiles(user_id uuid primary key references auth.users on delete cascade,created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.admin_profiles where user_id=auth.uid())$$;
create function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create function public.sync_completed_at() returns trigger language plpgsql set search_path='' as $$begin if new.status='completed' and old.status is distinct from 'completed' then new.completed_at=now();elsif new.status<>'completed' then new.completed_at=null;end if;return new;end$$;
create trigger leads_status before update of status on public.leads for each row execute function public.sync_completed_at();
create trigger leads_updated before update on public.leads for each row execute function public.touch_updated_at();
create trigger services_updated before update on public.services for each row execute function public.touch_updated_at();
create trigger areas_updated before update on public.service_areas for each row execute function public.touch_updated_at();
create view public.customer_service_metrics with (security_invoker=true) as select max(full_name) customer_name,max(email) email,max(phone) phone,coalesce(nullif(email_normalized,''),phone_normalized) customer_key,count(*) total_requests,count(*) filter(where status='completed') completed_services,max(completed_at) last_service_date from public.leads group by coalesce(nullif(email_normalized,''),phone_normalized);
alter table public.services enable row level security;alter table public.pricing_rules enable row level security;alter table public.service_areas enable row level security;alter table public.leads enable row level security;alter table public.lead_services enable row level security;alter table public.gallery enable row level security;alter table public.site_settings enable row level security;alter table public.admin_profiles enable row level security;
create policy "public reads active services" on public.services for select using(active or public.is_admin());
create policy "public reads active areas" on public.service_areas for select using(active or public.is_admin());
create policy "public reads published gallery" on public.gallery for select using(published or public.is_admin());
create policy "admins all services" on public.services for all using(public.is_admin()) with check(public.is_admin());create policy "admins pricing" on public.pricing_rules for all using(public.is_admin()) with check(public.is_admin());create policy "admins areas" on public.service_areas for all using(public.is_admin()) with check(public.is_admin());create policy "admins leads" on public.leads for all using(public.is_admin()) with check(public.is_admin());create policy "admins lead services" on public.lead_services for all using(public.is_admin()) with check(public.is_admin());create policy "admins gallery" on public.gallery for all using(public.is_admin()) with check(public.is_admin());create policy "admins settings" on public.site_settings for all using(public.is_admin()) with check(public.is_admin());create policy "admin reads profile" on public.admin_profiles for select using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('gallery','gallery',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public gallery objects" on storage.objects for select using(bucket_id='gallery');create policy "admins upload gallery" on storage.objects for insert to authenticated with check(bucket_id='gallery' and public.is_admin() and lower(storage.extension(name))=any(array['jpg','jpeg','png','webp']));create policy "admins manage gallery objects" on storage.objects for update to authenticated using(bucket_id='gallery' and public.is_admin());create policy "admins delete gallery objects" on storage.objects for delete to authenticated using(bucket_id='gallery' and public.is_admin());
